class 处理铃:
    def __init__(self):
        self.听众 = []

    def 订上(self, 对象):
        self.听众.append(对象)

    def 摇铃(self, 菜名):
        for 对象 in self.听众:
            对象.听见了(菜名)


class 对象:
    def __init__(self, 名字):
        self.名字 = 名字

    def 听见了(self, 菜名):
        print(self.名字, "冲向", 菜名)


class 学生丙:
    def __init__(self, 名字):
        self.名字 = 名字

    def 听见了(self, 菜名):
        print(self.名字, "翻个身，等", 菜名, "端过来")


铃 = 处理铃()
铃.订上(对象("张三"))
铃.订上(对象("李四"))
铃.订上(学生丙("三花"))
铃.摇铃("{d1}")
铃.摇铃("{d2}")
